MATCH (conversionSession:Session)-[:CONVERSION_REALIZADA]->(c:Conversion)

// Determinar la identidad del cliente final para la sesión de conversión
OPTIONAL MATCH (u:User)-[:REALIZO]->(conversionSession)
OPTIONAL MATCH (v:Visitor)-[:INICIO_SESION]->(conversionSession)
OPTIONAL MATCH (v)-[:IDENTIFIED_AS]->(identifiedUser:User)

// El cliente final es el User si la sesión fue realizada por uno,
// o el User al que se identificó el Visitor,
// o el Visitor mismo si nunca se identificó como User.
WITH conversionSession, c, COALESCE(u, identifiedUser, v) AS ultimateCustomer
WHERE ultimateCustomer IS NOT NULL

// Recopilar TODAS las sesiones asociadas con este cliente final
MATCH (ultimateCustomer)-[r]->(s:Session)
WHERE (ultimateCustomer:User AND type(r) = 'REALIZO') OR (ultimateCustomer:Visitor AND type(r) = 'INICIO_SESION')

// Si el cliente final es un User, también incluimos las sesiones de Visitors que se identificaron como este User
OPTIONAL MATCH (identifiedVisitor:Visitor)-[:IDENTIFIED_AS]->(ultimateCustomer)
OPTIONAL MATCH (identifiedVisitor)-[:INICIO_SESION]->(visitorSession:Session)

// Combinar todas las sesiones directas e indirectas del cliente final
WITH ultimateCustomer, conversionSession, c, COLLECT(DISTINCT s) AS directSessions, COLLECT(DISTINCT visitorSession) AS identifiedVisitorSessions
WITH ultimateCustomer, conversionSession, c, directSessions + identifiedVisitorSessions AS allCustomerSessions

// Filtrar cualquier sesión nula que pueda haber resultado de OPTIONAL MATCH
WITH ultimateCustomer, conversionSession, c, [s_item IN allCustomerSessions WHERE s_item IS NOT NULL] AS validCustomerSessions

// Desplegar y ordenar todas las sesiones válidas por fecha para cada cliente
UNWIND validCustomerSessions AS journeySession
WITH ultimateCustomer, conversionSession, c, journeySession
ORDER BY COALESCE(ultimateCustomer.user_id, ultimateCustomer.id), journeySession.date

// Recopilar las sesiones ordenadas por cliente para asignar un número de sesión (rank)
WITH ultimateCustomer, conversionSession, c, COLLECT(journeySession) AS orderedSessions

// Asignar el número de sesión (rank) a cada sesión dentro del viaje del cliente
