WITH ultimateCustomer, conversionSession, c, orderedSessions[idx] AS currentJourneySession, idx + 1 AS sessionNumber

// Filtrar para la sesión que realmente tuvo la conversión
WHERE currentJourneySession = conversionSession

// Contar las conversiones por número de sesión
RETURN sessionNumber, COUNT(c) AS numberOfConversions
ORDER BY numberOfConversions DESC
LIMIT 1

